<script setup lang="ts">import { ref } from 'vue';import { api,post } from '../../api/client';import AsyncState from '../../components/AsyncState.vue';const id=ref('pump-tank-v1'),item=ref<any>(),error=ref(''),loading=ref(false);async function load(){loading.value=true;error.value='';try{item.value=await api(`/asset-models/${id.value}`)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}async function validate(){loading.value=true;try{item.value={...item.value,validation:await post(`/asset-models/${id.value}/validate`,{})}}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}</script>
<template><section class="panel"><div class="panel-head"><div><h2>Asset registry</h2><p>Draft, validate, publish, and inspect topology.</p></div><div class="inline"><input v-model="id" aria-label="Model ID"><button @click="load">Open</button></div></div><AsyncState :loading="loading" :error="error" :empty="!item"><dl v-if="item" class="record"><dt>State</dt><dd>{{item.state}}</dd><dt>Version</dt><dd>{{item.version}}</dd><dt>Digest</dt><dd class="mono">{{item.digest}}</dd></dl><button v-if="item" @click="validate">Validate draft</button><pre v-if="item?.validation">{{item.validation}}</pre></AsyncState></section></template>
